<?php

declare(strict_types=1);

namespace JDR\Tests\Imaging;

use JDR\Imaging\DimensionGuard;
use JDR\Imaging\GifParser;
use JDR\Imaging\ImagePipeline;
use JDR\Imaging\ImageRejected;
use JDR\Imaging\Limits;
use JDR\Imaging\ProcessedImage;
use JDR\Imaging\Sniffer;
use JDR\Imaging\Thumbnailer;
use JDR\Imaging\WebpParser;
use PHPUnit\Framework\Attributes\DataProvider;

/**
 * The whole pipeline on the corpus tests/fixtures/uploads (generated by
 * dev/fixtures/make-uploads.php): valid files accepted with the right attributes, every trapped
 * file refused with the right code.
 */
final class ImagePipelineTest extends ImagingTestCase
{
    /**
     * @return array<string, array{0: string, 1: string, 2: int, 3: int, 4: bool, 5: int, 6: int}>
     */
    public static function validFiles(): array
    {
        // file, mime, width, height, animated, frames, duration ms
        return [
            'png opaque' => ['valid_png_opaque.png', 'image/png', 64, 48, false, 1, 0],
            'png transparent' => ['valid_png_transparent.png', 'image/png', 64, 64, false, 1, 0],
            'png with text chunks' => ['valid_png_text_chunk.png', 'image/png', 64, 48, false, 1, 0],
            'jpeg exif orientation 6' => ['valid_jpeg_exif_orientation6.jpg', 'image/jpeg', 40, 80, false, 1, 0],
            'webp lossy' => ['valid_webp_lossy.webp', 'image/webp', 64, 48, false, 1, 0],
            'webp lossless' => ['valid_webp_lossless.webp', 'image/webp', 48, 48, false, 1, 0],
            'gif animated' => ['valid_gif_animated.gif', 'image/gif', 32, 32, true, 10, 1000],
            'gif static' => ['valid_gif_static.gif', 'image/gif', 24, 24, false, 1, 0],
            'webp animated' => ['valid_webp_animated.webp', 'image/webp', 48, 32, true, 3, 300],
            'apng as still' => ['valid_apng.png', 'image/png', 32, 32, false, 1, 0],
        ];
    }

    /**
     * @return array<string, array{0: string, 1: string, 2: string}>
     */
    public static function trappedFiles(): array
    {
        return [
            'polyglot png+php' => ['trap_polyglot_png_php.png', 'unsupported_type', 'script_payload'],
            'polyglot png text <?=' => ['trap_polyglot_png_text_php.png', 'unsupported_type', 'script_payload'],
            'polyglot gif+php' => ['trap_polyglot_gif_php.gif', 'unsupported_type', 'script_payload'],
            'jpeg comment script' => ['trap_jpeg_comment_script.jpg', 'unsupported_type', 'script_payload'],
            'svg renamed' => ['trap_svg_renamed.png', 'unsupported_type', 'unknown_signature'],
            'html renamed' => ['trap_html_renamed.png', 'unsupported_type', 'unknown_signature'],
            'php' => ['trap_php_pure.png', 'unsupported_type', 'unknown_signature'],
            'bmp renamed' => ['trap_bmp_renamed.png', 'unsupported_type', 'unknown_signature'],
            'tiff renamed' => ['trap_tiff_renamed.png', 'unsupported_type', 'unknown_signature'],
            'heic renamed' => ['trap_heic_renamed.png', 'unsupported_type', 'unknown_signature'],
            'empty' => ['trap_empty.png', 'unsupported_type', 'empty_file'],
            'png bomb 50000' => ['trap_png_bomb_50000.png', 'image_too_large', 'dimension_exceeded'],
            'png 20000 announced' => ['trap_png_huge_20000.png', 'image_too_large', 'dimension_exceeded'],
            'png bad crc' => ['trap_png_bad_crc.png', 'unsupported_type', 'png_bad_crc'],
            'png truncated' => ['trap_png_truncated.png', 'unsupported_type', 'png_truncated'],
            'gif 1000 frames' => ['trap_gif_1000_frames.gif', 'animation_too_long', 'too_many_frames'],
            'gif 25 s' => ['trap_gif_25s.gif', 'animation_too_long', 'duration_exceeded'],
            'gif broken' => ['trap_gif_broken.gif', 'unsupported_type', 'gif_invalid'],
            'gif unknown block' => ['trap_gif_bad_block.gif', 'unsupported_type', 'gif_invalid'],
            'webp bad riff size' => ['trap_webp_bad_riff_size.webp', 'unsupported_type', 'webp_size_mismatch'],
            'jpeg truncated' => ['trap_jpeg_truncated.jpg', 'unsupported_type', 'jpeg_truncated'],
        ];
    }

    #[DataProvider('validFiles')]
    public function testValidFileIsAccepted(
        string $file,
        string $mime,
        int $width,
        int $height,
        bool $animated,
        int $frames,
        int $durationMs,
    ): void {
        $source = self::fixture($file);
        $before = hash_file('sha256', $source);
        $result = (new ImagePipeline())->process($source, new Limits(), $this->work);

        self::assertSame($mime, $result->mime);
        self::assertSame(array_search($mime, Sniffer::MIME, true), (new Sniffer())->sniff($result->path));
        self::assertSame(Sniffer::EXT[array_search($mime, Sniffer::MIME, true)], $result->ext);
        self::assertStringEndsWith('.' . $result->ext, $result->path);
        self::assertSame([$width, $height], [$result->width, $result->height]);
        self::assertSame($animated, $result->isAnimated);
        self::assertSame($frames, $result->frameCount);
        self::assertSame($durationMs, $result->durationMs);
        // Final file: in the work dir, size and SHA-256 of the FINAL bytes.
        self::assertSame($this->work, dirname($result->path));
        self::assertSame(filesize($result->path), $result->sizeBytes);
        self::assertSame(hash_file('sha256', $result->path), $result->sha256);
        self::assertSame($before, hash_file('sha256', $source), 'The input file must not be modified.');
        $size = getimagesize($result->path);
        self::assertIsArray($size);
        self::assertSame([$width, $height], [$size[0], $size[1]]);
        $this->assertThumbnail($result, $width, $height);
        self::assertCount(2, $this->workFiles());
    }

    #[DataProvider('trappedFiles')]
    public function testTrappedFileIsRefused(string $file, string $code, string $reason): void
    {
        $e = self::assertRejected(
            fn () => (new ImagePipeline())->process(self::fixture($file), new Limits(), $this->work),
            $code,
            $reason,
        );
        self::assertSame('', $e->getMessage(), 'Nothing technical may reach the client.');
        self::assertNotSame('', $e->detail());
        self::assertSame([], $this->workFiles(), 'A refusal leaves no file behind.');
    }

    public function testEveryFixtureIsCovered(): void
    {
        $covered = array_merge(
            array_column(self::validFiles(), 0),
            array_column(self::trappedFiles(), 0),
        );
        $files = array_map('basename', glob(JDR_ROOT . '/tests/fixtures/uploads/*') ?: []);
        sort($covered);
        sort($files);
        self::assertSame($files, $covered);
    }

    public function testGifRewriteDropsCommentAndApplicationButKeepsLoop(): void
    {
        $source = file_get_contents(self::fixture('valid_gif_animated.gif'));
        self::assertStringContainsString('JDR-TEST-GIF-COMMENT', $source);
        self::assertStringContainsString('XMP DataXMP', $source);

        $result = (new ImagePipeline())->process(self::fixture('valid_gif_animated.gif'), new Limits(), $this->work);
        $final = (string) file_get_contents($result->path);
        self::assertStringNotContainsString('JDR-TEST-GIF-COMMENT', $final);
        self::assertStringNotContainsString('XMP DataXMP', $final);
        self::assertStringNotContainsString('JDR-TEST-GIF-XMP', $final);
        self::assertSame(1, substr_count($final, 'NETSCAPE2.0'));
        self::assertSame(strlen($source) - strlen("\x21\xFE\x14JDR-TEST-GIF-COMMENT\0")
            - strlen("\x21\xFF\x0BXMP DataXMP\x10JDR-TEST-GIF-XMP\0"), strlen($final));
        $again = (new GifParser())->parse($final);
        self::assertSame(10, $again->frameCount);
        self::assertSame(1000, $again->durationMs);
        self::assertSame($final, $again->cleanData, 'The rewrite is stable.');
        self::assertInstanceOf(\GdImage::class, @imagecreatefromstring($final));
    }

    public function testWebpRewriteDropsMetadataAndFixesRiffSize(): void
    {
        $source = (string) file_get_contents(self::fixture('valid_webp_animated.webp'));
        foreach (['EXIF', 'XMP ', 'ICCP', 'JDR-TEST-JUNK'] as $marker) {
            self::assertStringContainsString($marker, $source);
        }
        $result = (new ImagePipeline())->process(self::fixture('valid_webp_animated.webp'), new Limits(), $this->work);
        $final = (string) file_get_contents($result->path);
        foreach (['EXIF', 'XMP ', 'ICCP', 'JDR-TEST-EXIF', 'JDR-TEST-XMP', 'JDR-TEST-ICC', 'JDR-TEST-JUNK'] as $marker) {
            self::assertStringNotContainsString($marker, $final);
        }
        self::assertSame(strlen($final) - 8, unpack('V', substr($final, 4, 4))[1], 'RIFF size');
        self::assertSame('VP8X', substr($final, 12, 4));
        self::assertSame(WebpParser::FLAG_ALPHA | WebpParser::FLAG_ANIMATION, ord($final[20]), 'VP8X flags');
        self::assertSame(3, substr_count($final, 'ANMF'));
        self::assertSame(1, substr_count($final, 'ANIM'));
        $again = (new WebpParser())->parse($final);
        self::assertSame($final, $again->cleanData, 'The rewrite is stable.');
        self::assertSame(3, $again->frameCount);
    }

    public function testAnimatedWebpThumbnailUsesTheFirstFrame(): void
    {
        $result = (new ImagePipeline())->process(self::fixture('valid_webp_animated.webp'), new Limits(), $this->work);
        $thumb = imagecreatefromstring((string) file_get_contents($result->thumbPath));
        self::assertInstanceOf(\GdImage::class, $thumb);
        // Not the generic 256x256 thumbnail: the canvas size of the first frame.
        self::assertSame([48, 32], [imagesx($thumb), imagesy($thumb)]);
    }

    public function testStillImagesAreReencodedWithoutMetadata(): void
    {
        $png = (new ImagePipeline())->process(self::fixture('valid_png_text_chunk.png'), new Limits(), $this->work);
        $bytes = (string) file_get_contents($png->path);
        self::assertStringNotContainsString('tEXt', $bytes);
        self::assertStringNotContainsString('zTXt', $bytes);
        self::assertStringNotContainsString('JDR-TEST', $bytes);

        $apng = (new ImagePipeline())->process(self::fixture('valid_apng.png'), new Limits(), $this->work);
        $bytes = (string) file_get_contents($apng->path);
        self::assertStringNotContainsString('acTL', $bytes);
        self::assertStringNotContainsString('fcTL', $bytes);
        self::assertStringNotContainsString('fdAT', $bytes);
    }

    public function testJpegOrientationIsApplied(): void
    {
        $result = (new ImagePipeline())->process(self::fixture('valid_jpeg_exif_orientation6.jpg'), new Limits(), $this->work);
        $bytes = (string) file_get_contents($result->path);
        self::assertStringNotContainsString('Exif', $bytes);
        $image = imagecreatefromjpeg($result->path);
        self::assertInstanceOf(\GdImage::class, $image);
        self::assertSame([40, 80], [imagesx($image), imagesy($image)]);
        $top = imagecolorsforindex($image, imagecolorat($image, 20, 10));
        $bottom = imagecolorsforindex($image, imagecolorat($image, 20, 70));
        self::assertGreaterThan(200, $top['red']);
        self::assertLessThan(60, $top['blue']);
        self::assertGreaterThan(200, $bottom['blue']);
        self::assertLessThan(60, $bottom['red']);
    }

    public function testTransparencyIsPreserved(): void
    {
        foreach (['valid_png_transparent.png' => [64, 64], 'valid_webp_lossless.webp' => [48, 48]] as $file => [$w, $h]) {
            $result = (new ImagePipeline())->process(self::fixture($file), new Limits(), $this->work);
            $image = imagecreatefromstring((string) file_get_contents($result->path));
            self::assertInstanceOf(\GdImage::class, $image);
            $corner = imagecolorsforindex($image, imagecolorat($image, 0, 0));
            $center = imagecolorsforindex($image, imagecolorat($image, intdiv($w, 2), intdiv($h, 2)));
            self::assertGreaterThan(100, $corner['alpha'], $file);
            self::assertLessThan(10, $center['alpha'], $file);
        }
    }

    public function testLosslessWebpStaysLossless(): void
    {
        $result = (new ImagePipeline())->process(self::fixture('valid_webp_lossless.webp'), new Limits(), $this->work);
        self::assertTrue((new WebpParser())->parse((string) file_get_contents($result->path))->lossless);
        $lossy = (new ImagePipeline())->process(self::fixture('valid_webp_lossy.webp'), new Limits(), $this->work);
        self::assertFalse((new WebpParser())->parse((string) file_get_contents($lossy->path))->lossless);
    }

    public function testLargeImageThumbnailIsAtMost256(): void
    {
        $image = imagecreatetruecolor(600, 300);
        imagefill($image, 0, 0, imagecolorallocate($image, 10, 120, 200));
        $path = $this->work . '/input.png';
        imagepng($image, $path);

        $result = (new ImagePipeline())->process($path, new Limits(), $this->work);
        self::assertSame([600, 300], [$result->width, $result->height]);
        $size = getimagesize($result->thumbPath);
        self::assertIsArray($size);
        self::assertSame([256, 128], [$size[0], $size[1]]);
        self::assertSame('image/webp', $result->thumbMime);
        self::assertSame(filesize($result->thumbPath), $result->thumbSizeBytes);
        unlink($path);
    }

    public function testConfigurableLimits(): void
    {
        $pipeline = new ImagePipeline();
        self::assertRejected(
            fn () => $pipeline->process(self::fixture('valid_png_transparent.png'), new Limits(maxBytes: 100), $this->work),
            ImageRejected::FILE_TOO_LARGE,
            'file_too_large',
        );
        self::assertRejected(
            fn () => $pipeline->process(self::fixture('valid_png_opaque.png'), new Limits(maxDimension: 63), $this->work),
            ImageRejected::IMAGE_TOO_LARGE,
            'dimension_exceeded',
        );
        self::assertRejected(
            fn () => $pipeline->process(self::fixture('valid_png_opaque.png'), new Limits(maxTotalPixels: 3000), $this->work),
            ImageRejected::IMAGE_TOO_LARGE,
            'pixel_count_exceeded',
        );
        self::assertRejected(
            fn () => $pipeline->process(self::fixture('valid_gif_animated.gif'), new Limits(maxFrames: 9), $this->work),
            ImageRejected::ANIMATION_TOO_LONG,
            'too_many_frames',
        );
        self::assertRejected(
            fn () => $pipeline->process(self::fixture('valid_webp_animated.webp'), new Limits(maxFrames: 2), $this->work),
            ImageRejected::ANIMATION_TOO_LONG,
            'too_many_frames',
        );
        self::assertRejected(
            fn () => $pipeline->process(self::fixture('valid_webp_animated.webp'), new Limits(maxAnimationMs: 299), $this->work),
            ImageRejected::ANIMATION_TOO_LONG,
            'duration_exceeded',
        );
        self::assertSame([], $this->workFiles());
        $ok = $pipeline->process(self::fixture('valid_webp_animated.webp'), new Limits(maxFrames: 3, maxAnimationMs: 300), $this->work);
        self::assertSame(3, $ok->frameCount);
    }

    public function testMemoryCheckRefusesBeforeDecoding(): void
    {
        // 64 x 48 x 5 + 8 MB > 8 MB available.
        $pipeline = new ImagePipeline(guard: new DimensionGuard(availableMemory: 8 * 1024 * 1024));
        self::assertRejected(
            fn () => $pipeline->process(self::fixture('valid_png_opaque.png'), new Limits(), $this->work),
            ImageRejected::IMAGE_TOO_LARGE,
            'memory_exceeded',
        );
        $enough = new ImagePipeline(guard: new DimensionGuard(availableMemory: 9 * 1024 * 1024));
        self::assertSame(64, $enough->process(self::fixture('valid_png_opaque.png'), new Limits(), $this->work)->width);
    }

    public function testGenericThumbnail(): void
    {
        $thumb = (new Thumbnailer())->generic($this->work . '/generic');
        $size = getimagesize($thumb['path']);
        self::assertIsArray($size);
        self::assertSame([256, 256], [$size[0], $size[1]]);
        self::assertSame('image/webp', $thumb['mime']);
    }

    private function assertThumbnail(ProcessedImage $result, int $width, int $height): void
    {
        self::assertSame($this->work, dirname($result->thumbPath));
        self::assertSame('image/webp', $result->thumbMime);
        self::assertStringEndsWith('_thumb.webp', $result->thumbPath);
        self::assertSame(filesize($result->thumbPath), $result->thumbSizeBytes);
        $size = getimagesize($result->thumbPath);
        self::assertIsArray($size);
        self::assertLessThanOrEqual(256, max($size[0], $size[1]));
        // Small fixtures are never upscaled.
        self::assertSame([$width, $height], [$size[0], $size[1]]);
    }
}
